using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Net;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;
namespace NightLens {
static class ImageServiceTests {
 static void Pump(Func<bool> done){var watch=System.Diagnostics.Stopwatch.StartNew();while(!done()&&watch.ElapsedMilliseconds<4000){Application.DoEvents();Thread.Sleep(5);}}
 public static void Run(string[] args,List<string> log){Action<bool,string> check=(ok,message)=>{if(!ok)throw new Exception(message);log.Add("PASS: "+message);};var previousFolder=ObjectImages.CacheFolder;var previousDownloader=ObjectImages.Downloader;try{ObjectImages.CacheFolder=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[4])),"image-service-regressions",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(ObjectImages.CacheFolder);byte[] valid=File.ReadAllBytes(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Assets","Objects","Moon.jpg"));var pelican=new Target("Pelican Nebula","Emission nebula",20.8502,44.4015,60,50){Canonical="IC5070"};var urls=new List<string>();ObjectImages.Downloader=url=>{urls.Add(url);if(url.Contains("//alasky."))throw new WebException("Test timeout",WebExceptionStatus.Timeout);return valid;};string file=ObjectImages.Get(pelican,true).GetAwaiter().GetResult();check(file!=null&&File.Exists(file)&&urls.Count==2&&urls[1].Contains("alaskybis.cds.unistra.fr"),"Pelican picture falls back to the independent mirror when the primary server times out");check(Directory.GetFiles(ObjectImages.CacheFolder,"*.tmp").Length==0,"Successful image fetch leaves no partial cache files");int requests=urls.Count;check(ObjectImages.Get(pelican,false).Result==file&&urls.Count==requests,"Equipment changes reuse a complete cached image without another download");
 File.WriteAllText(file,"broken partial PNG");ObjectImages.Downloader=url=>valid;check(ObjectImages.Get(pelican,true,true).Result==file&&new FileInfo(file).Length>1000,"Corrupt cached pictures are detected and replaced atomically");
 var other=new Target("Other target","Galaxy",10,20,30,20);int errors=0;ObjectImages.Downloader=url=>{errors++;throw new WebException("Test timeout",WebExceptionStatus.Timeout);};check(ObjectImages.Get(other,true).Result==null&&errors==2&&ObjectImages.ErrorFor(other).Contains("too long"),"Server timeouts report the actual problem rather than claiming the computer is offline");ObjectImages.Get(other,true).Wait();check(errors==2,"Repeated paints do not repeatedly hit an unavailable image server");ObjectImages.Downloader=url=>valid;check(ObjectImages.Get(other,true,true).Result!=null,"An explicit retry bypasses the temporary failure cooldown immediately");
 var shared=new Target("Shared pending image","Galaxy",11,25,25,15);using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim()){ObjectImages.Downloader=url=>{entered.Set();release.Wait(3000);return valid;};var first=ObjectImages.Get(shared,true);check(entered.Wait(1000),"Image request starts asynchronously");var second=ObjectImages.Get(shared,true);check(ReferenceEquals(first,second)&&!File.Exists(ObjectImages.PathFor(shared)),"Switching equipment shares an in-progress download and cannot see a half-written cache file");release.Set();check(first.Result!=null&&second.Result==first.Result,"All waiting object views receive the completed picture");}
 var automatic=new Target("Automatic retry image","Nebula",12,30,20,15);int tries=0;ObjectImages.Downloader=url=>{if(Interlocked.Increment(ref tries)<=2)throw new WebException("Test temporary failure",WebExceptionStatus.Timeout);return valid;};using(var form=new Form()){Style.Form(form);form.Size=new Size(350,350);var photo=new ObjectPhoto(automatic,true){Dock=DockStyle.Fill};((System.Windows.Forms.Timer)typeof(ObjectPhoto).GetField("retry",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(photo)).Interval=50;form.Controls.Add(photo);form.Show();Pump(()=>photo.HasImage);check(photo.HasImage&&tries==3,"Visible picture retries automatically after a temporary failure and updates without changing targets");form.Close();}
 var manual=new Target("Manual retry image","Nebula",13,35,20,15);ObjectImages.Downloader=url=>{throw new WebException("Test unavailable",WebExceptionStatus.Timeout);};using(var form=new Form()){Style.Form(form);var photo=new ObjectPhoto(manual,true){Dock=DockStyle.Fill};form.Controls.Add(photo);form.Show();Pump(()=>photo.StatusText.Contains("Retrying automatically"));check(photo.StatusText.Contains("too long")&&photo.Cursor==Cursors.Hand,"Failed photo offers an accurate message and click-to-retry action");ObjectImages.Downloader=url=>valid;typeof(Control).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(photo,new object[]{EventArgs.Empty});Pump(()=>photo.HasImage);check(photo.HasImage&&photo.Cursor==Cursors.Default,"Clicking a failed photo reloads it without adding image enlargement");form.Close();}
 }finally{ObjectImages.CacheFolder=previousFolder;ObjectImages.Downloader=previousDownloader;}}
}
}
